def is_valid_parentheses(s: str) -> bool:
    mapping = {')': '(', '}': '{', ']': '['}
    stack = []
    for ch in s:
        if ch in mapping:
            top = stack.pop() if stack else '#'
            if mapping[ch] != top:
                return False
        else:
            stack.append(ch)
    return not stack
